T["pathophysiology"]["summary"] += " A practical rule makes self-titration safe: adjust basal insulin by 2 units every 3 days towards the fasting target, and stop escalating once the dose passes about 0.5 units/kg without control."
T["presentation"]["symptoms"] += ["Blurred vision, recurrent infections (genital candidiasis, skin)", "Nocturnal sweating or morning headache (nocturnal hypoglycaemia)"]
T["presentation"]["physicalSigns"] += ["Low BMI or rapid weight loss despite treatment (insulin deficiency)", "Acanthosis nigricans (insulin resistance)"]
T["differentials"] = [{"condition": c, "distinguishingFeatures": f} for c, f in [
 ("Latent autoimmune diabetes in adults (LADA)", "Lean adult whose oral drugs fail within months; GAD antibodies positive and C-peptide low — needs insulin early."),
 ("Pancreatic (fibrocalculous) diabetes", "Common in parts of India: young, lean, recurrent abdominal pain and steatorrhoea; pancreatic calcification on X-ray or ultrasound; needs insulin and enzymes."),
 ("Steroid-induced hyperglycaemia", "Afternoon and evening glucose rise on prednisolone or dexamethasone with near-normal fasting values; morning NPH or prandial insulin fits the pattern."),
 ("Type 1 diabetes presenting in adulthood", "Weight loss, ketones and low C-peptide; needs basal-bolus insulin from diagnosis, never oral drugs alone."),
 ("Overbasalisation rather than true insulin resistance", "Basal dose above 0.5 U/kg, bedtime-to-morning glucose fall of 50 mg/dL or more, or hypoglycaemia; add prandial insulin instead of more basal."),
 ("Somogyi or dawn phenomenon", "High fasting glucose explained by a 2–3 am check: low at night (too much evening insulin) or normal at night with a dawn rise.")]]
T["clinicalManagement"][1]["actions"] = ["Patient adjusts basal dose by 2 units every 3 days until fasting glucose reaches target (80–130 mg/dL) (ADA guide; ICMR T2DM).", "Any hypoglycaemia: find the cause and lower the dose (ADA guide).", "Basal above 0.5 U/kg without control, or bedtime-to-morning fall 50 mg/dL or more: stop escalating basal (ADA 2025; ADA guide)."]
T["clinicalManagement"].insert(3, step("prandial-adjust", "Adjust prandial insulin", "Every few days", ["Titrate prandial dose by post-meal readings (no step size stated in the opened sources); if HbA1c below 8% when adding prandial, reduce basal by 4 units or 10% (ADA guide).", "Hypoglycaemia on prandial insulin: reduce that dose by 10–20% (ADA guide)."]))
